<?php
/**
 * A plugin's own registry update check (generated by tools/build/gen-registry-updates.py), run on its own with stand-ins
 * for WordPress. Usage: php tools/validate/registry-updates-plugin-test.php <slug> <function prefix> <file relative to the plugin>
 */
// phpcs:disable -- a command-line test runner with WordPress stubs.
list( , $slug, $p, $rel ) = $argv + array( '', '', '', '' );
define( 'ABSPATH', __DIR__ . '/' );
define( 'HOUR_IN_SECONDS', 3600 );
$GLOBALS['hooks'] = array();
$GLOBALS['tr']    = array();
$GLOBALS['reg']   = null;
$GLOBALS['dl']    = null;
class WP_Error { public $code; function __construct( $c = '' ) { $this->code = $c; } }
function is_wp_error( $x ) { return $x instanceof WP_Error; }
function add_filter( $t, $cb ) { $GLOBALS['hooks'][ $t ][] = $cb; }
function add_action( $t, $cb ) { $GLOBALS['hooks'][ $t ][] = $cb; }
function apply_filters( $t, $v ) { return $v; }
function get_option( $n, $d = false ) { return $d; }
function esc_url_raw( $u ) { return $u; }
function __( $s ) { return $s; }
function get_site_transient( $k ) { return $GLOBALS['tr'][ $k ] ?? false; }
function set_site_transient( $k, $v ) { $GLOBALS['tr'][ $k ] = $v; }
function delete_site_transient( $k ) { unset( $GLOBALS['tr'][ $k ] ); }
function wp_remote_get( $u, $a ) { return $GLOBALS['reg']; }
function wp_remote_retrieve_response_code( $r ) { return $r['code']; }
function wp_remote_retrieve_body( $r ) { return $r['body']; }
function download_url( $u ) { return $GLOBALS['dl']; }
function wp_delete_file( $f ) { @unlink( $f ); }
require dirname( __DIR__, 2 ) . "/plugins/$slug/$rel";
$fail = 0;
$ok   = function ( $n, $c ) use ( &$fail ) { if ( ! $c ) { $fail++; echo "FAIL: $n\n"; } };
$upd  = $GLOBALS['hooks']['update_plugins_wugweb.com'][0];
$pre  = $GLOBALS['hooks']['upgrader_pre_download'][0];
$file = tempnam( sys_get_temp_dir(), 'kreg' );
file_put_contents( $file, 'zipbytes' );
$sha  = hash( 'sha256', 'zipbytes' );
$pkg  = "https://github.com/wugweb-git/Kits/releases/download/$slug-v9.9.9/$slug.zip";
$entry = array( 'released' => true, 'prerelease' => false, 'version' => '9.9.9', 'page' => 'https://wugweb-git.github.io/Kits/plugins/' . $slug . '/',
	'requires_wp' => '6.5', 'requires_php' => '8.0', 'tested' => '7.1', 'download' => array( 'commercial' => $pkg ), 'sha256' => array( 'commercial' => $sha ) );
$serve = function ( $mut = null ) use ( $slug, $entry ) {
	$e = $entry;
	if ( $mut ) { $mut( $e ); }
	$GLOBALS['tr'] = array();
	$GLOBALS['reg'] = array( 'code' => 200, 'body' => json_encode( array( 'products' => array( $slug => $e ) ) ) );
};
$data = array( 'Version' => '1.0.0', 'UpdateURI' => "https://wugweb.com/plugins/$slug/" );

$serve();
$r = $upd( false, $data, "$slug/$slug.php" );
$ok( "$slug: a newer stable release is offered", is_array( $r ) && '9.9.9' === $r['version'] && $pkg === $r['package'] && $slug === $r['slug'] );
$ok( "$slug: the same version is not offered", false === $upd( false, array( 'Version' => '9.9.9' ), "$slug/$slug.php" ) );
$ok( "$slug: another plugin's file is not answered", false === $upd( false, $data, "other/other.php" ) );
$serve( function ( &$e ) { $e['prerelease'] = true; } );
$ok( "$slug: a pre-release is not offered on the stable channel", false === $upd( false, $data, "$slug/$slug.php" ) );
$serve( function ( &$e ) { $e['download']['commercial'] = 'https://evil.example/x.zip'; } );
$ok( "$slug: another host's package is refused", false === $upd( false, $data, "$slug/$slug.php" ) );
$serve( function ( &$e ) { $e['version'] = '9.9.9; drop'; } );
$ok( "$slug: a odd version string is refused", false === $upd( false, $data, "$slug/$slug.php" ) );
$GLOBALS['tr'] = array();
$GLOBALS['reg'] = array( 'code' => 500, 'body' => '' );
$ok( "$slug: an unreachable registry offers nothing", false === $upd( false, $data, "$slug/$slug.php" ) );
$ok( "$slug: a failed check is remembered", array() === ( $GLOBALS['tr'][ $p . '_registry' ] ?? null ) );

$serve();
$GLOBALS['dl'] = $file;
$ok( "$slug: a download with the right checksum is kept", $file === $pre( false, $pkg ) );
$GLOBALS['dl'] = $file;
$serve( function ( &$e ) { $e['sha256']['commercial'] = str_repeat( 'a', 64 ); } );
$ok( "$slug: a download with the wrong checksum is refused", is_wp_error( $pre( false, $pkg ) ) );
$serve( function ( &$e ) { $e['sha256']['commercial'] = ''; } );
$ok( "$slug: no published checksum is refused", is_wp_error( $pre( false, $pkg ) ) );
$serve();
$ok( "$slug: another product's package is left alone", false === $pre( false, 'https://github.com/wugweb-git/Kits/releases/download/other-v1/other.zip' ) );
$ok( "$slug: a file from another host is left alone", false === $pre( false, 'https://evil.example/x.zip' ) );

if ( true ) { function kits_registry_offer() {} } // declared now, not hoisted: Core's updater being present.
$serve();
$ok( "$slug: stands down when Kits Core answers", false === $upd( false, $data, "$slug/$slug.php" ) );
@unlink( $file );
echo $fail ? "$fail failed\n" : "$slug: registry updates ok\n";
exit( $fail ? 1 : 0 );
